67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
73	
74	    private final ClinicService clinicService;
75	
76	    private final OwnerMapper ownerMapper;
77	
78	    private final PetMapper petMapper;
79	
80	    private final VisitMapper visitMapper;
81	
82	    private final TelephoneNormalizer telephoneNormalizer;
83	
84	    private final AddressNormalizer addressNormalizer;
85	
86	    private final EmailNormalizer emailNormalizer;
87	
88	    public OwnerRestControllerV1(ClinicService clinicService,
89	                                 OwnerMapper ownerMapper,
90	                                 PetMapper petMapper,
91	                                 VisitMapper visitMapper,
92	                                 TelephoneNormalizer telephoneNormalizer,
93	                                 AddressNormalizer addressNormalizer,
94	                                 EmailNormalizer emailNormalizer) {
95	        this.clinicService = clinicService;
96	        this.ownerMapper = ownerMapper;
97	        this.petMapper = petMapper;
98	        this.visitMapper = visitMapper;
99	        this.telephoneNormalizer = telephoneNormalizer;
100	        this.addressNormalizer = addressNormalizer;
101	        this.emailNormalizer = emailNormalizer;
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
107	        Collection<Owner> owners;
108	        if (lastName != null) {
109	            owners = this.clinicService.findOwnerByLastName(lastName);
110	        } else {
111	            owners = this.clinicService.findAllOwners();
112	        }
113	        if (owners.isEmpty()) {
114	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
115	        }
116	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
117	    }
118	
119	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
120	    @Override
121	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
122	        return withOwner(ownerId, owner ->
123	            new ResponseEntity<>(toOwnerDtoWithDerivedFields(owner), HttpStatus.OK));
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
129	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
130	        rejectBlankOwnerFields(ownerFieldsDto);
131	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
132	        if (!sharesHousehold) {
133	            rejectDuplicateHousehold(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
134	        }
135	        rejectCityAtCapacity(ownerFieldsDto.getCity());
136	        LocalDate registrationDate = businessDay(effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate()));
137	        rejectDailyRegistrationLimit(registrationDate);
138	        String normalizedTelephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
139	        rejectDuplicateTelephone(normalizedTelephone);
140	        ownerFieldsDto.setTelephone(normalizedTelephone);
141	        String normalizedEmail = emailNormalizer.normalize(ownerFieldsDto.getEmail());
142	        rejectDuplicateEmail(normalizedEmail);
143	        ownerFieldsDto.setEmail(normalizedEmail);
144	        HttpHeaders headers = new HttpHeaders();
145	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
146	        owner.setRegistrationDate(registrationDate);
147	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
148	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
149	        if (sharesHousehold) {
150	            owner.setHouseholdId(householdId(owner.getLastName(), owner.getAddress()));
151	        }
152	        this.clinicService.saveOwner(owner);
153	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
154	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
155	            ownerMapper.membershipLevel(owner));
156	        OwnerDto ownerDto = toOwnerDtoWithDerivedFields(owner);
157	        headers.setLocation(UriComponentsBuilder.newInstance()
158	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
159	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
160	    }
161	
162	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
163	    @Override
164	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
165	        return withOwner(ownerId, currentOwner -> {
166	            currentOwner.setAddress(ownerFieldsDto.getAddress());
167	            currentOwner.setCity(ownerFieldsDto.getCity());
168	            currentOwner.setFirstName(ownerFieldsDto.getFirstName());
169	            currentOwner.setLastName(ownerFieldsDto.getLastName());
170	            currentOwner.setTelephone(ownerFieldsDto.getTelephone());
171	            currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
172	            this.clinicService.saveOwner(currentOwner);
173	            return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
174	        });
175	    }
176	
177	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
178	    @Transactional
179	    @Override
180	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
181	        return withOwner(ownerId, owner -> {
182	            this.clinicService.deleteOwner(owner);
183	            return new ResponseEntity<>(HttpStatus.NO_CONTENT);
184	        });
185	    }
186	
187	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
188	    @Override
189	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
190	        return withOwner(ownerId, owner -> {
191	            HttpHeaders headers = new HttpHeaders();
192	            Pet pet = petMapper.toPet(petFieldsDto);
193	            owner.setId(ownerId);
194	            pet.setOwner(owner);
195	            pet.getType().setName(null);
196	            this.clinicService.savePet(pet);
197	            PetDto petDto = petMapper.toPetDto(pet);
198	            headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
199	                .buildAndExpand(pet.getId()).toUri());
200	            return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
201	        });
202	    }
203	
204	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
205	    @Override
206	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
207	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
208	        if (currentOwner != null) {
209	            Pet currentPet = this.clinicService.findPetById(petId);
210	            if (currentPet != null) {
211	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
212	                currentPet.setName(petFieldsDto.getName());
213	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
214	                this.clinicService.savePet(currentPet);
215	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
216	            }
217	        }
218	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
219	    }
220	
221	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
222	    @Override
223	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
224	        HttpHeaders headers = new HttpHeaders();
225	        Visit visit = visitMapper.toVisit(visitFieldsDto);
226	        Pet pet = new Pet();
227	        pet.setId(petId);
228	        visit.setPet(pet);
229	        this.clinicService.saveVisit(visit);
230	        VisitDto visitDto = visitMapper.toVisitDto(visit);
231	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
232	            .buildAndExpand(visit.getId()).toUri());
233	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
234	    }
235	
236	
237	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
238	    @Override
239	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
240	        Owner owner = this.clinicService.findOwnerById(ownerId);
241	        if (owner != null) {
242	            Pet pet = owner.getPet(petId);
243	            if (pet != null) {
244	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
245	            }
246	        }
247	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
248	    }
249	
250	    /**
251	     * Loads the owner with the given id and, when it exists, produces the response through
252	     * {@code action}; when no such owner exists a {@code 404 Not Found} is returned instead. The
253	     * single-owner endpoints share this "find the owner or report 404" preamble, so the lookup and
254	     * the not-found response are written in exactly one place rather than copied into each method.
255	     *
256	     * @param ownerId the id of the owner to load
257	     * @param action builds the response for an existing owner
258	     * @param <T> the response body type
259	     * @return the result of {@code action} for an existing owner, otherwise a 404 response
260	     */
261	    private <T> ResponseEntity<T> withOwner(Integer ownerId, Function<Owner, ResponseEntity<T>> action) {
262	        Owner owner = this.clinicService.findOwnerById(ownerId);
263	        if (owner == null) {
264	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
265	        }
266	        return action.apply(owner);
267	    }
268	
269	    /**
270	     * Maps a persisted owner to its {@link OwnerDto} and populates the read-only fields that are
271	     * derived from server-side state rather than stored columns (currently the
272	     * {@code bulkSignupWarning} flag). Both the create endpoint and the single-owner read endpoint
273	     * return their owner through this method, so an owner is decorated identically on either path
274	     * and each derived field is computed in exactly one place.
275	     *
276	     * @param owner the persisted owner to represent
277	     * @return the owner DTO with its derived read-only fields populated
278	     */
279	    private OwnerDto toOwnerDtoWithDerivedFields(Owner owner) {
280	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
281	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
282	        return ownerDto;
283	    }
284	
285	    /**
286	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
287	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
288	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
289	     * blank (e.g. {@code "   "}). The offending field names are reported through an
290	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
291	     * as a 400 response carrying an {@code errors} array of field names.
292	     *
293	     * @param ownerFieldsDto the submitted owner fields
294	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
295	     */
296	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
297	        List<String> blankFields = new ArrayList<>();
298	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
299	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
300	        addIfBlank(blankFields, "address", ownerFieldsDto.getAddress());
301	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
302	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
303	        if (!blankFields.isEmpty()) {
304	            throw new InvalidOwnerFieldsException(blankFields);
305	        }
306	    }
307	
308	    private void addIfBlank(List<String> blankFields, String field, String value) {
309	        if (value != null && value.isBlank()) {
310	            blankFields.add(field);
311	        }
312	    }
313	
314	    /**
315	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
316	     * {@code '<CITY3>-<LAST3>-<NNNN>'}: {@code CITY3} is the upper-cased first three letters of the
317	     * owner's {@code city}, {@code LAST3} is the upper-cased first three letters of the owner's
318	     * {@code lastName}, and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one
319	     * more than the number of owners already in that city (e.g. {@code 'MEL-SMI-0007'}).
320	     *
321	     * @param city the city of the owner being created
322	     * @param lastName the last name of the owner being created
323	     * @return the formatted customer code
324	     */
325	    private String nextCustomerCode(String city, String lastName) {
326	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(java.util.Locale.ROOT);
327	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(java.util.Locale.ROOT);
328	        long sequence = ownersInCity(city) + 1L;
329	        return String.format("%s-%s-%04d", city3, last3, sequence);
330	    }
331	
332	    /**
333	     * Counts how many existing owners already share the given {@code firstName} and {@code lastName},
334	     * compared case-insensitively (using {@link java.util.Locale#ROOT}-independent
335	     * {@link String#equalsIgnoreCase(String)}). The count reflects the owners present before the
336	     * current create, so a name that is unique on create yields {@code 0}. The value is stored on the
337	     * new owner and surfaced as the read-only {@code namesakeCount} field.
338	     *
339	     * @param firstName the first name of the owner being created
340	     * @param lastName the last name of the owner being created
341	     * @return the number of existing owners with the same first and last name (case-insensitive)
342	     */
343	    private int namesakeCount(String firstName, String lastName) {
344	        return (int) this.clinicService.findAllOwners().stream()
345	            .filter(owner -> equalsIgnoreCase(owner.getFirstName(), firstName)
346	                && equalsIgnoreCase(owner.getLastName(), lastName))
347	            .count();
348	    }
349	
350	    private boolean equalsIgnoreCase(String a, String b) {
351	        return a == null ? b == null : a.equalsIgnoreCase(b);
352	    }
353	
354	    /**
355	     * The maximum number of owners a single city may contain. Once a city already holds this many
356	     * owners, further owners in that city are rejected by {@link #rejectCityAtCapacity(String)}.
357	     */
358	    private static final long MAX_OWNERS_PER_CITY = 50L;
359	
360	    /**
361	     * Rejects a create request whose city already contains {@link #MAX_OWNERS_PER_CITY} or more
362	     * owners. Existing owners are matched to the requested city case-insensitively (using
363	     * {@link java.util.Locale#ROOT}-independent {@link String#equalsIgnoreCase(String)}), mirroring
364	     * the per-city counting used for the customer code. A city at capacity is reported through an
365	     * {@link OwnerCityAtCapacityException}, which the {@code ExceptionControllerAdvice} renders as a
366	     * 409 Conflict response.
367	     *
368	     * @param city the city of the owner being created
369	     * @throws OwnerCityAtCapacityException if the city already holds the maximum number of owners
370	     */
371	    private void rejectCityAtCapacity(String city) {
372	        if (ownersInCity(city) >= MAX_OWNERS_PER_CITY) {
373	            throw new OwnerCityAtCapacityException(city);
374	        }
375	    }
376	
377	    /**
378	     * Counts the existing owners whose {@code city} matches the given city, compared
379	     * case-insensitively (see {@link #equalsIgnoreCase(String, String)}). Shared by the per-city
380	     * customer-code sequence ({@link #nextCustomerCode(String, String)}) and the per-city capacity
381	     * check ({@link #rejectCityAtCapacity(String)}) so both count a city's owners identically.
382	     *
383	     * @param city the city to count owners for
384	     * @return the number of existing owners in that city
385	     */
386	    private long ownersInCity(String city) {
387	        return this.clinicService.findAllOwners().stream()
388	            .filter(owner -> equalsIgnoreCase(owner.getCity(), city))
389	            .count();
390	    }
391	
392	    /**
393	     * The maximum number of owners that may be registered on a single day. Once this many owners
394	     * already carry a given {@code registrationDate}, further owners for that date are rejected by
395	     * {@link #rejectDailyRegistrationLimit(LocalDate)}.
396	     */
397	    private static final long MAX_OWNERS_PER_DAY = 100L;
398	
399	    /**
400	     * Resolves the effective registration date for a create request: the value supplied in the
401	     * request when present, otherwise the server's current date. The result is the raw effective
402	     * date before the business-day adjustment applied by {@link #businessDay(LocalDate)}.
403	     *
404	     * @param suppliedDate the registration date from the request, or {@code null} when omitted
405	     * @return the supplied date, or today when none was supplied
406	     */
407	    private LocalDate effectiveRegistrationDate(LocalDate suppliedDate) {
408	        return suppliedDate != null ? suppliedDate : LocalDate.now();
409	    }
410	
411	    /**
412	     * Adjusts a date so it falls on a business day. A Saturday is rolled forward to the following
413	     * Monday and a Sunday to the next day (Monday); any weekday is returned unchanged. Applied to
414	     * the effective registration date so that a weekend value - whether supplied in the request or
415	     * defaulted to the server date - is stored as the next Monday, and every value derived from the
416	     * registration date (such as the membership number's year segment and the daily create-limit
417	     * bucket) uses the adjusted business day.
418	     *
419	     * @param date the effective registration date
420	     * @return the same date when it is a weekday, otherwise the next Monday
421	     */
422	    private LocalDate businessDay(LocalDate date) {
423	        DayOfWeek dayOfWeek = date.getDayOfWeek();
424	        if (dayOfWeek == DayOfWeek.SATURDAY) {
425	            return date.plusDays(2);
426	        }
427	        if (dayOfWeek == DayOfWeek.SUNDAY) {
428	            return date.plusDays(1);
429	        }
430	        return date;
431	    }
432	
433	    /**
434	     * Rejects a create request once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
435	     * created on the given day, counted by {@code registrationDate}. A day at capacity is reported
436	     * through a {@link DailyOwnerRegistrationLimitException}, which the {@code ExceptionControllerAdvice}
437	     * renders as a 429 Too Many Requests response.
438	     *
439	     * @param date the registration date of the owner being created (today)
440	     * @throws DailyOwnerRegistrationLimitException if the day already holds the maximum number of owners
441	     */
442	    private void rejectDailyRegistrationLimit(LocalDate date) {
443	        if (ownersRegisteredOn(date) >= MAX_OWNERS_PER_DAY) {
444	            throw new DailyOwnerRegistrationLimitException(date);
445	        }
446	    }
447	
448	    /**
449	     * Counts the existing owners whose {@code registrationDate} equals the given day. Shared by the
450	     * hard daily create limit ({@link #rejectDailyRegistrationLimit(LocalDate)}) and the soft
451	     * {@code bulkSignupWarning} flag ({@link #bulkSignupWarning(LocalDate)}) so both accumulate a
452	     * day's owners identically.
453	     *
454	     * @param date the registration date to count owners for
455	     * @return the number of existing owners registered on that day
456	     */
457	    private long ownersRegisteredOn(LocalDate date) {
458	        return this.clinicService.findAllOwners().stream()
459	            .filter(owner -> date.equals(owner.getRegistrationDate()))
460	            .count();
461	    }
462	
463	    /**
464	     * The soft daily create threshold above which the read-only {@code bulkSignupWarning} flag is
465	     * raised. Once more than this many owners share a {@code registrationDate}, that day is flagged
466	     * as unusually high volume - a warning well below the hard {@link #MAX_OWNERS_PER_DAY} cap.
467	     */
468	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
469	
470	    /**
471	     * Derives the read-only {@code bulkSignupWarning} flag for an owner: {@code true} when more than
472	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have been created (counted by
473	     * {@code registrationDate}) on the given day, otherwise {@code false}. Uses the same per-day
474	     * accumulation as {@link #rejectDailyRegistrationLimit(LocalDate)}. A {@code null} date (an owner
475	     * without a registration date, such as seed data) is never flagged.
476	     *
477	     * @param date the owner's registration date (the day it was created), or {@code null}
478	     * @return {@code true} if the day already holds more than the warning threshold of owners
479	     */
480	    private boolean bulkSignupWarning(LocalDate date) {
481	        if (date == null) {
482	            return false;
483	        }
484	        return ownersRegisteredOn(date) > BULK_SIGNUP_WARNING_THRESHOLD;
485	    }
486	
487	    /**
488	     * Rejects a create request whose normalized telephone is already used by any existing owner.
489	     * Existing owners' telephones are reduced to the same canonical form (via
490	     * {@link TelephoneNormalizer#canonicalize(String)}) before comparison, so numbers that differ
491	     * only in formatting still collide. A collision is reported through a
492	     * {@link DuplicateOwnerTelephoneException}, which the {@code ExceptionControllerAdvice} renders
493	     * as a 409 Conflict response.
494	     *
495	     * @param normalizedTelephone the canonical telephone of the owner being created
496	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone
497	     */
498	    private void rejectDuplicateTelephone(String normalizedTelephone) {
499	        boolean duplicate = existingOwnerMatches(
500	            owner -> owner.getTelephone() == null ? null : telephoneNormalizer.canonicalize(owner.getTelephone()),
501	            normalizedTelephone);
502	        if (duplicate) {
503	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
504	        }
505	    }
506	
507	    /**
508	     * Rejects a create request whose normalized (lower-cased) email is already used by any existing
509	     * owner. Existing owners' emails are reduced to the same canonical form (via
510	     * {@link EmailNormalizer#normalize(String)}, i.e. lower-cased) before comparison, so addresses
511	     * that differ only in casing still collide. Owners without an email are ignored, and a request
512	     * without an email is never rejected. A collision is reported through a
513	     * {@link DuplicateOwnerEmailException}, which the {@code ExceptionControllerAdvice} renders as a
514	     * 409 Conflict response.
515	     *
516	     * @param normalizedEmail the canonical (lower-cased) email of the owner being created, or
517	     * {@code null} when none was supplied
518	     * @throws DuplicateOwnerEmailException if another owner already uses this email
519	     */
520	    private void rejectDuplicateEmail(String normalizedEmail) {
521	        if (normalizedEmail == null) {
522	            return;
523	        }
524	        boolean duplicate = existingOwnerMatches(
525	            owner -> emailNormalizer.normalize(owner.getEmail()),
526	            normalizedEmail);
527	        if (duplicate) {
528	            throw new DuplicateOwnerEmailException(normalizedEmail);
529	        }
530	    }
531	
532	    /**
533	     * Reports whether any existing owner already carries the given comparison {@code key}, derived
534	     * from each owner by {@code keyExtractor}. Owners for which the extractor yields {@code null}
535	     * are ignored. The create endpoint's duplicate checks use this to reduce both an existing owner
536	     * and the owner being created to the same canonical key and reject a match.
537	     *
538	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
539	     * @param key the canonical key of the owner being created
540	     * @return {@code true} if some existing owner shares the key
541	     */
542	    private boolean existingOwnerMatches(Function<Owner, String> keyExtractor, String key) {
543	        return this.clinicService.findAllOwners().stream()
544	            .map(keyExtractor)
545	            .filter(Objects::nonNull)
546	            .anyMatch(key::equals);
547	    }
548	
549	    /**
550	     * Rejects a create request that shares a household with an existing owner: another owner already
551	     * has the same {@code lastName} and the same {@code address}. Both values are compared in
552	     * canonical form (case-insensitive with surrounding and internal whitespace collapsed to a single
553	     * space, see {@link #canonicalizeHousehold(String)}), so values that differ only in casing or
554	     * spacing still collide. A collision is reported through a {@link DuplicateOwnerHouseholdException},
555	     * which the {@code ExceptionControllerAdvice} renders as a 409 Conflict response. Callers skip this
556	     * check when the request opts in via {@code sharesHousehold}.
557	     *
558	     * @param lastName the last name of the owner being created
559	     * @param address the address of the owner being created
560	     * @throws DuplicateOwnerHouseholdException if another owner already shares the household
561	     */
562	    private void rejectDuplicateHousehold(String lastName, String address) {
563	        String canonicalLastName = canonicalizeHousehold(lastName);
564	        String canonicalAddress = canonicalizeHousehold(address);
565	        String key = householdKey(lastName, address);
566	        if (key == null) {
567	            return;
568	        }
569	        boolean duplicate = existingOwnerMatches(
570	            owner -> householdKey(owner.getLastName(), owner.getAddress()), key);
571	        if (duplicate) {
572	            throw new DuplicateOwnerHouseholdException(canonicalLastName, canonicalAddress);
573	        }
574	    }
575	
576	    /**
577	     * Delimiter joining the canonical household fields into a single comparison key. A run of
578	     * whitespace is collapsed to a single space by {@link #canonicalizeHousehold(String)}, so this
579	     * newline can never occur inside a canonical value and the two fields cannot bleed into one
580	     * another across the join.
581	     */
582	    private static final String HOUSEHOLD_KEY_DELIMITER = "\n";
583	
584	    /**
585	     * Reduces an owner's household fields ({@code lastName} and {@code address}) to a single
586	     * canonical comparison key - the two canonical fields (see {@link #canonicalizeHousehold(String)})
587	     * joined by {@link #HOUSEHOLD_KEY_DELIMITER} - or {@code null} when either field is absent. Two
588	     * owners share a household exactly when their household keys are equal, so
589	     * {@link #rejectDuplicateHousehold(String, String)} can detect a collision by comparing this one
590	     * key through {@link #existingOwnerMatches(Function, String)} rather than the two fields separately.
591	     *
592	     * @param lastName the owner's last name, or {@code null}
593	     * @param address the owner's address, or {@code null}
594	     * @return the canonical household key, or {@code null} when either field is {@code null}
595	     */
596	    private String householdKey(String lastName, String address) {
597	        String canonicalLastName = canonicalizeHousehold(lastName);
598	        String canonicalAddress = canonicalizeHousehold(address);
599	        if (canonicalLastName == null || canonicalAddress == null) {
600	            return null;
601	        }
602	        return canonicalLastName + HOUSEHOLD_KEY_DELIMITER + canonicalAddress;
603	    }
604	
605	    /**
606	     * Reduces a household field ({@code lastName} or {@code address}) to a canonical form for
607	     * case-insensitive, whitespace-insensitive comparison: leading and trailing whitespace is
608	     * trimmed, every run of internal whitespace is collapsed to a single space, and the result is
609	     * lower-cased using {@link java.util.Locale#ROOT} so comparison is locale-independent.
610	     *
611	     * @param value the raw field value, or {@code null}
612	     * @return the canonical value, or {@code null} when {@code value} is {@code null}
613	     */
614	    private String canonicalizeHousehold(String value) {
615	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
616	    }
617	
618	    /**
619	     * Derives the stable, shared {@code householdId} for an owner joining a household via
620	     * {@code sharesHousehold}. The identifier is a deterministic function of the canonical
621	     * {@code lastName} and {@code address} (see {@link #canonicalizeHousehold(String)}), so every
622	     * owner with the same last name at the same address - regardless of casing or spacing - is
623	     * assigned the identical value. It is the first 16 upper-case hex characters of the SHA-256 hash
624	     * of the two canonical fields joined by a delimiter that cannot occur in the input.
625	     *
626	     * @param lastName the last name of the owner being created
627	     * @param address the address of the owner being created
628	     * @return the shared household identifier
629	     */
630	    private String householdId(String lastName, String address) {
631	        String key = canonicalizeHousehold(lastName) + HOUSEHOLD_KEY_DELIMITER + canonicalizeHousehold(address);
632	        try {
633	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
634	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
635	            StringBuilder sb = new StringBuilder(digest.length * 2);
636	            for (byte b : digest) {
637	                sb.append(String.format("%02X", b));
638	            }
639	            return sb.substring(0, 16);
640	        } catch (java.security.NoSuchAlgorithmException e) {
641	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
642	        }
643	    }
644	}
